class Product {
  private final BigDecimal price;
  Product(BigDecimal price) {
    if (price.compareTo(BigDecimal.ZERO) <= 0) throw new IllegalArgumentException("Cena musi byc dodatnia");
    this.price = price;
  }
}
new Product(new BigDecimal("10")); // OK
try { new Product(new BigDecimal("-10")); } catch (IllegalArgumentException e) { System.out.println(e.getMessage()); }

record CartItem(Product product, int quantity) {}
class ShoppingCart {
  private final List<CartItem> items = new ArrayList<>();
  void addItem(Product product, int quantity) {
    if (quantity <= 0) throw new IllegalArgumentException("Ilosc musi byc dodatnia");
    items.add(new CartItem(product, quantity));
  }
}

BigDecimal getTotalValue() {
  return items.stream()
    .map(item -> item.product().unitPrice().multiply(BigDecimal.valueOf(item.quantity())))
    .reduce(BigDecimal.ZERO, BigDecimal::add);
}

static Product fromRawValues(String name, String priceAsText, String quantityAsText) {
  return new Product(name, new BigDecimal(priceAsText), Integer.parseInt(quantityAsText));
}
Product p1 = new Product("A", new BigDecimal("10"), 5);
Product p2 = fromRawValues("A", "10", "5");
