class BankAccount {
  private BigDecimal balance;
  BankAccount(BigDecimal balance) { this.balance = balance; }
  void withdraw(BigDecimal amount) {
    if (amount.compareTo(balance) > 0) throw new IllegalStateException("Niewystarczajace srodki");
    balance = balance.subtract(amount);
  }
}

enum OrderStatus { NEW, PAID, SHIPPED }
class Order {
  private OrderStatus status = OrderStatus.NEW;
  void markAsPaid() {
    if (status != OrderStatus.NEW) throw new IllegalStateException("Mozna oplacic tylko nowe zamowienie");
    status = OrderStatus.PAID;
  }
  void markAsShipped() {
    if (status != OrderStatus.PAID) throw new IllegalStateException("Mozna wyslac tylko oplacone zamowienie");
    status = OrderStatus.SHIPPED;
  }
}

record Money(BigDecimal amount, String currency) {
  Money add(Money other) {
    if (!currency.equals(other.currency())) throw new IllegalArgumentException("Rozne waluty");
    return new Money(amount.add(other.amount()), currency);
  }
}

