class ShoppingCart {
  private final Map<Product, Integer> items = new LinkedHashMap<>();
  void addItem(Product product, int quantity) {
    if (items.size() >= 10 && !items.containsKey(product)) throw new IllegalStateException("Maksymalnie 10 pozycji");
    items.merge(product, quantity, Integer::sum);
  }
  void checkout() {
    if (getTotalValue().compareTo(new BigDecimal("20")) < 0) throw new IllegalStateException("Minimalna wartosc zamowienia 20zl");
  }
}

record Money(BigDecimal amount, String currency) {
  Money add(Money other) { /* jak w Zadaniu 15 */ return new Money(amount.add(other.amount()), currency); }
  Money subtract(Money other) { return new Money(amount.subtract(other.amount()), currency); }
  Money multiply(int factor) { return new Money(amount.multiply(BigDecimal.valueOf(factor)), currency); }
}

