@FunctionalInterface interface Specification<T> { boolean isSatisfiedBy(T candidate); }
static List<Order> filterOrders(List<Order> orders, Specification<Order>... specs) {
  return orders.stream().filter(o -> Arrays.stream(specs).allMatch(s -> s.isSatisfiedBy(o))).toList();
}
